class FileHandle {
  #fd;                                        // brand: no clone path copies it
  constructor(fd) { this.#fd = fd; }
  static open(path) { return new FileHandle(fs.openSync(path, 'r')); }
  read(n) { return fs.readSync(this.#fd, Buffer.alloc(n)); }
}

